import fs from "fs";
import path from "path";

export default function handler(req, res) {
  if (req.method !== "GET") {
    return res.status(405).json({ error: "Método no permitido" });
  }

  const uploadDir = path.join(process.cwd(), "public/uploads");

  // Crear carpeta si no existe
  if (!fs.existsSync(uploadDir)) {
    fs.mkdirSync(uploadDir, { recursive: true });
  }

  try {
    const files = fs.readdirSync(uploadDir);

    // Filtrar solo imágenes
    const images = files
      .filter(file => /\.(jpe?g|png|gif|webp|mp4)$/i.test(file)) // agregué mp4 si querés mostrar videos también
      .map(file => `/uploads/${file}`);

    return res.status(200).json({ images });
  } catch (err) {
    console.error("Error leyendo carpeta uploads:", err);
    return res.status(500).json({ error: "No se pudieron listar los archivos" });
  }
}
